// DravenIQ Lead Follow-up Digest v1.0.0. No external dependencies.
const REQUIRED = ['lead_id', 'name', 'status', 'follow_up_date', 'next_action'];
const OPEN = new Set(['new', 'contacted', 'qualified', 'proposal']);
const CLOSED = new Set(['won', 'lost', 'archived']);
const clean = value => value === undefined || value === null ? '' : String(value).trim();
const escapeHtml = value => clean(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shorten = (value, limit) => clean(value).length > limit ? clean(value).slice(0, limit) + '…' : clean(value);

function isDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value) || value < '1900-01-01' || value > '2199-12-31') return false;
  const d = new Date(value + 'T00:00:00.000Z');
  return Number.isFinite(d.getTime()) && d.toISOString().slice(0, 10) === value;
}

function validateConfig(input) {
  const c = {...input};
  for (const key of ['sendEmails', 'allowManualSend', 'sendEmptyDigest']) {
    if (typeof c[key] !== 'boolean') throw new Error(key + ' must be true or false, without quotes.');
  }
  if (!isDate(c.today)) throw new Error('The execution date must be YYYY-MM-DD.');
  c.previewDate = clean(c.previewDate);
  if (c.previewDate && !isDate(c.previewDate)) throw new Error('previewDate must be empty or a valid YYYY-MM-DD date.');
  if (c.previewDate && (c.executionMode !== 'test' || c.sendEmails)) throw new Error('previewDate is for manual previews with sendEmails=false. Clear it before sending or scheduling.');
  if (!['test', 'production'].includes(c.executionMode)) throw new Error('Unsupported execution mode. Run from the Manual Preview or Daily Schedule trigger.');
  c.spreadsheetId = clean(c.spreadsheetId);
  c.sheetName = clean(c.sheetName);
  c.ownerEmail = clean(c.ownerEmail);
  if (!/^[A-Za-z0-9_-]{15,200}$/.test(c.spreadsheetId) || c.spreadsheetId.includes('PASTE_')) throw new Error('Set spreadsheetId to the ID between /d/ and /edit in your Google Sheets URL.');
  if (!c.sheetName || c.sheetName.length > 100 || /[\r\n]/.test(c.sheetName)) throw new Error('Set sheetName to your tab name, normally Leads.');
  if (!c.timezone || typeof c.timezone !== 'string') throw new Error('Set a valid workflow timezone in Settings.');
  // Deliberately supports one ordinary address, without display names or lists.
  if (c.ownerEmail && !/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)+$/.test(c.ownerEmail)) throw new Error('ownerEmail must contain one email address, with no display name, commas or spaces.');
  if (c.sendEmails && (!c.ownerEmail || /@(?:example\.(?:com|org|net)|[^@]+\.invalid)$/i.test(c.ownerEmail))) throw new Error('Set ownerEmail to your real test inbox before enabling email.');
  if (!Number.isInteger(c.maxItemsPerSection) || c.maxItemsPerSection < 1 || c.maxItemsPerSection > 20) throw new Error('maxItemsPerSection must be an integer from 1 to 20.');
  c.asOfDate = c.previewDate || c.today;
  return c;
}


return [{json: validateConfig({...$input.first().json, today: $now.toISODate(), timezone: $now.zoneName, executionMode: $execution.mode})}];

