function readHistory(state) {
  if (!state || typeof state !== 'object' || Array.isArray(state)) throw new Error('Workflow static data is unavailable.');
  const h = state.leadDigestV1;
  if (h === undefined) return [];
  if (!Array.isArray(h) || h.some(e => !e || typeof e.key !== 'string' || typeof e.messageId !== 'string' || typeof e.sentAt !== 'string')) throw new Error('Digest delivery history is malformed. Inspect static data before retrying.');
  return h;
}

function buildDigest(rows, config, state = {}) {
  const c = validateConfig(config);
  if (!Array.isArray(rows)) throw new Error('Expected Google Sheets rows.');
  if (rows.length > 5000) throw new Error('More than 5,000 rows were returned. Archive older leads or reduce the source sheet.');
  const groups = {overdue: [], dueToday: [], needsAttention: []};
  const counts = {nonblankRows: 0, uniqueRecords: 0, overdue: 0, dueToday: 0, needsAttention: 0, future: 0, closed: 0, duplicateRows: 0, blankRows: 0};
  const warnings = [];
  const seen = new Map();
  const nonblank = rows.filter(r => r && Object.entries(r).some(([k,v]) => k !== 'row_number' && clean(v) !== ''));
  if (nonblank.length && REQUIRED.some(k => !nonblank.some(r => Object.prototype.hasOwnProperty.call(r, k)))) throw new Error('Missing required column(s). Use exactly: ' + REQUIRED.join(', ') + '.');
  rows.forEach((raw, index) => {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid row at input position ' + (index + 1));
    if (!Object.entries(raw).some(([k,v]) => k !== 'row_number' && clean(v) !== '')) { counts.blankRows++; return; }
    counts.nonblankRows++;
    const record = Object.fromEntries(REQUIRED.map(k => [k, clean(raw[k])]));
    record.status = record.status.toLowerCase();
    const rowNumber = Number(raw.row_number);
    record.source = Number.isInteger(rowNumber) && rowNumber >= 2 ? 'Sheet row ' + rowNumber : 'Input record ' + (index + 1);
    const fingerprint = JSON.stringify(REQUIRED.map(k => record[k]));
    if (record.lead_id) {
      if (seen.has(record.lead_id)) {
        if (seen.get(record.lead_id) !== fingerprint) throw new Error('Conflicting records for lead_id ' + shorten(record.lead_id, 80) + '. Keep one current row per lead.');
        counts.duplicateRows++; return;
      }
      seen.set(record.lead_id, fingerprint);
    }
    counts.uniqueRecords++;
    if (CLOSED.has(record.status)) { counts.closed++; return; }
    const issues = [];
    if (!record.lead_id) issues.push('Add a unique lead_id');
    if (!record.name) issues.push('Add a name');
    if (!OPEN.has(record.status)) issues.push('Use an allowed status');
    if (!isDate(record.follow_up_date)) issues.push(record.follow_up_date ? 'Fix follow_up_date: use YYYY-MM-DD' : 'Add follow_up_date');
    if (!record.next_action) issues.push('Add next_action');
    if (issues.length) {
      record.issues = issues;
      groups.needsAttention.push(record);
      return;
    }
    if (record.follow_up_date < c.asOfDate) {
      record.daysOverdue = Math.round((Date.parse(c.asOfDate + 'T00:00:00Z') - Date.parse(record.follow_up_date + 'T00:00:00Z')) / 86400000);
      groups.overdue.push(record);
    } else if (record.follow_up_date === c.asOfDate) groups.dueToday.push(record);
    else counts.future++;
  });
  const compare = (a,b) => a.follow_up_date.localeCompare(b.follow_up_date) || a.lead_id.localeCompare(b.lead_id);
  groups.overdue.sort(compare); groups.dueToday.sort(compare);
  for (const key of Object.keys(groups)) counts[key] = groups[key].length;
  if (!counts.nonblankRows) warnings.push('No nonblank rows returned. Check the selected document, tab and headers; headers cannot be verified on an empty result.');
  if (counts.duplicateRows) warnings.push(counts.duplicateRows + ' identical duplicate row(s) ignored.');
  if (counts.blankRows && counts.nonblankRows) warnings.push(counts.blankRows + ' blank input row(s) ignored.');
  const total = counts.overdue + counts.dueToday + counts.needsAttention;
  const key = JSON.stringify(['lead-digest-v1', c.spreadsheetId, c.sheetName, c.ownerEmail, c.timezone, c.asOfDate]);
  const history = readHistory(state);
  let sendAllowed = false;
  let deliveryStatus;
  if (!c.sendEmails) deliveryStatus = 'preview_only';
  else if (c.executionMode === 'test' && !c.allowManualSend) deliveryStatus = 'manual_send_disabled';
  else if (c.executionMode !== 'test' && history.some(e => e.key === key)) deliveryStatus = 'already_sent_today';
  else if (!total && !c.sendEmptyDigest) deliveryStatus = 'nothing_to_follow_up';
  else { sendAllowed = true; deliveryStatus = c.executionMode === 'test' ? 'ready_for_manual_test' : 'ready_to_send'; }
  const sheetUrl = 'https://docs.google.com/spreadsheets/d/' + c.spreadsheetId + '/edit#range=' + encodeURIComponent("'" + c.sheetName.replace(/'/g,"''") + "'!A1:E5001");
  const shown = Object.fromEntries(Object.entries(groups).map(([k,v]) => [k, v.slice(0, c.maxItemsPerSection)]));
  const subject = '[DravenIQ] Lead follow-up ' + c.asOfDate + ': ' + counts.overdue + ' overdue, ' + counts.dueToday + ' due today, ' + counts.needsAttention + ' to fix';
  const titles = {overdue:'Overdue', dueToday:'Due today', needsAttention:'Needs attention'};
  let text = 'LEAD FOLLOW-UP DIGEST\n' + c.asOfDate + ' (' + c.timezone + ')\n\n';
  let sections = '';
  for (const k of Object.keys(groups)) {
    text += titles[k] + ': ' + counts[k] + '\n';
    let cards = '';
    for (const r of shown[k]) {
      const name = shorten(r.name || '(missing name)', 80);
      const id = shorten(r.lead_id || '(missing ID)', 60);
      const date = shorten(r.follow_up_date || '(missing date)', 40);
      const action = shorten(r.next_action || '(missing next action)', 240);
      const detail = k === 'overdue' ? r.daysOverdue + ' day(s) overdue' : k === 'needsAttention' ? r.issues.join('; ') : 'Follow up today';
      text += '- ' + id + ' | ' + name + ' | ' + date + '\n  ' + action + '\n  ' + detail + ' (' + r.source + ')\n';
      cards += '<div style="padding:12px 0;border-bottom:1px solid #e1e7ef"><strong>' + escapeHtml(name) + '</strong> <span style="color:#58677a">' + escapeHtml(id) + '</span><p style="margin:6px 0">' + escapeHtml(action) + '</p><div style="font-size:13px;color:#58677a">' + escapeHtml(date) + ' · ' + escapeHtml(detail) + ' · ' + escapeHtml(r.source) + '</div></div>';
    }
    if (!shown[k].length) { text += 'None.\n'; cards = '<p style="color:#58677a">None.</p>'; }
    const omitted = counts[k] - shown[k].length;
    if (omitted) { text += omitted + ' more in the sheet.\n'; cards += '<p>' + omitted + ' more in the sheet. Search by lead ID to review all records.</p>'; }
    text += '\n';
    sections += '<section style="margin:24px 0"><h2 style="font-size:18px;margin:0">' + titles[k] + ' (' + counts[k] + ')</h2>' + cards + '</section>';
  }
  const note = 'After following up, update next_action and follow_up_date. Set status to won, lost or archived when finished.';
  const scope = counts.future + ' future lead(s) and ' + counts.closed + ' closed lead(s) excluded.';
  text += scope + '\n' + (warnings.length ? warnings.join('\n') + '\n' : '') + '\n' + note + '\nOpen lead tracker: ' + sheetUrl;
  const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f4f7fb;color:#152238;font:15px Arial,sans-serif;line-height:1.5"><main style="max-width:640px;margin:24px auto;background:#fff;border:1px solid #dde5ee;padding:24px"><div style="font-size:13px;font-weight:bold;color:#075f73">DravenIQ / LEAD FOLLOW-UP</div><h1 style="font-size:25px;margin:8px 0">Your follow-up list</h1><p style="color:#58677a">' + escapeHtml(c.asOfDate) + ' · ' + escapeHtml(c.timezone) + '</p>' + sections + '<p style="font-size:13px;color:#58677a">' + escapeHtml(scope) + '</p>' + (warnings.length ? '<p style="background:#fff4d6;padding:12px">' + warnings.map(escapeHtml).join('<br>') + '</p>' : '') + '<p><a style="display:inline-block;background:#152238;color:#fff;padding:10px 16px;text-decoration:none;border-radius:4px" href="' + escapeHtml(sheetUrl) + '">Open lead tracker</a></p><p style="font-size:13px;color:#58677a">' + note + '</p></main></body></html>';
  return {templateVersion:'1.0.0', asOfDate:c.asOfDate, timezone:c.timezone, ownerEmail:c.ownerEmail, executionMode:c.executionMode, counts, warnings, sendAllowed, deliveryStatus, deliveryKey:key, subject, text, html, sheetUrl, shown};
}

function recordDelivery(digest, gmail, state, sentAt) {
  if (digest.sendAllowed !== true) throw new Error('Refusing to record a digest that was not approved for sending.');
  if (!gmail || typeof gmail.id !== 'string' || !gmail.id) throw new Error('Gmail returned no message ID. Check Sent mail before any retry.');
  if (digest.executionMode === 'test') return {deliveryStatus:'manual_test_sent', messageId:gmail.id, historySaved:false, note:'Manual tests do not save production delivery history.'};
  if (digest.executionMode !== 'production') throw new Error('Unsupported delivery mode.');
  const history = readHistory(state).filter(e => e.key !== digest.deliveryKey);
  history.push({key:digest.deliveryKey, messageId:gmail.id, sentAt});
  state.leadDigestV1 = history.slice(-180);
  return {deliveryStatus:'sent', messageId:gmail.id, asOfDate:digest.asOfDate, historySaved:'pending_successful_execution', note:'Best-effort daily history; not an atomic lock.'};
}


return [{json: buildDigest($input.all().map(i => i.json), $('Validate settings').first().json, $getWorkflowStaticData('global'))}];

